		fields = strings.Fields(line)
		stuffings[i].a, _ = fmt.Sscanf(fields[0], "%d")
		stuffings[i].b, _ = fmt.Sscanf(fields[1], "%d")
		stuffings[i].c, _ = fmt.Sscanf(fields[2], "%d")
		stuffings[i].d, _ = fmt.Sscanf(fields[3], "%d")
	}

	// dp[dough] = max money
	// We'll use a 2D DP: dp[i][dough] = max money using first i stuffings with 'dough' grams remaining
	// Actually, let's think differently.
	// Let dp[dough] = max money we can get with 'dough' grams of dough available, considering all stuffings.
	// But we need to track how much of each stuffing we've used.

	// Alternative approach:
	// For each stuffing i, we can make at most ai/bi buns.
	// Let's use DP where state is (dough_used, stuffing1_used, ..., stuffinmgm_used) - too many dimensions.

	// Better: Process stuffings one by one.
	// dp[i][d] = max money using first i stuffings and having used exactly d grams of dough.
	// But we also need to know how much of each stuffing we used.

	// Actually, since m <= 10 and n <= 1000, and each stuffing can be used at most 100/bi <= 100 times,
	// we can do:
	// dp[i][d] = max money using first i stuffings with d grams of dough used.
	// For each stuffing i, we decide how many buns to make (0 to ai/bi).

	// Let's define:
	// dp[i][d] = max money using first i stuffings (0-indexed, so i from 0 to m) with d grams of dough used.
	// Initially dp[0][0] = 0, others = -infinity.

	// For each stuffing i (0 to m-1), and for each possible number of buns k (0 to ai/bi):
	//   dough_used = k * ci
	//   money = k * di
	//   dp[i+1][d + dough_used] = max(dp[i+1][d + dough_used], dp[i][d] + money)

	// After processing all m stuffings, we have dp[m][d] for d from 0 to n.
	// Then we can add plain buns: for each d, remaining dough = n - d.
	// Number of plain buns = (n - d) / c0
	// Total money = dp[m][d] + ((n - d) / c0) * d0

	// Initialize dp
	const NEG_INF = -1 << 30
	dp := make([][]int, m+1)
	for i := 0; i <= m; i++ {
		dp[i] = make([]int, n+1)
		for j := 0; j <= n; j++ {
			dp[i][j] = NEG_INF
		}
	}
