	for i := 0; i < m; i++ {
		a := stuffings[i].a
		b := stuffings[i].b
		c := stuffings[i].c
		d := stuffings[i].d
		maxBuns := a / b

		for doughUsed := 0; doughUsed <= n; doughUsed++ {
			if dp[i][doughUsed] == NEG_INF {
				continue
			}
			for k := 0; k <= maxBuns; k++ {
				doughCost := k * c
				if doughUsed + doughCost > n {
					break
				}
