				newVal := dp[i][doughUsed] + money
				if newVal > dp[i+1][doughUsed+doughCost] {
					dp[i+1][doughUsed+doughCost] = newVal
				}
			}
		}
	}

	// Now compute the answer by adding plain buns
	ans := 0
	for doughUsed := 0; doughUsed <= n; doughUsed++ {
		if dp[m][doughUsed] == NEG_INF {
			continue
		}
		remainingDough := n - doughUsed
		plainBuns := remainingDough / c0
		totalMoney := dp[m][doughUsed] + plainBuns*d0
		if totalMoney > ans {
			ans = totalMoney
		}
	}

