		parts := strings.Fields(string(line))
		fmt.Sscanf(parts[0], "%d", &a[i])
		fmt.Sscanf(parts[1], "%d", &b[i])
		fmt.Sscanf(parts[2], "%d", &c[i])
		fmt.Sscanf(parts[3], "%d", &d[i])
	}

	// dp[i][j] = max money using first i stuffings with j grams of dough used
	// We'll use 1D DP over dough, iterating over stuffings
	// dp[j] = max money with j grams of dough used after processing some stuffings

	maxDough := n
	dp := make([]int, maxDough+1)
	// Initialize with -infinity except dp[0] = 0
	for j := 0; j <= maxDough; j++ {
		dp[j] = -1 << 31
	}
	dp[0] = 0

	// Process each stuffing type
	for i := 0; i < m; i++ {
		// For each stuffing i, we can make k buns where k * b[i] <= a[i] and k * c[i] <= remaining dough
		// We do unbounded knapsack style but bounded by a[i]
		// new_dp[j] = max over k: dp[j - k*c[i]] + k*d[i] where k*b[i] <= a[i]
		newDp := make([]int, maxDough+1)
		for j := 0; j <= maxDough; j++ {
			newDp[j] = dp[j] // k = 0
		}
		// For each possible number of buns k
		maxK := a[i] / b[i]
		for k := 1; k <= maxK; k++ {
			cost := k * c[i]
			profit := k * d[i]
			if cost > maxDough {
				break
			}
			for j := cost; j <= maxDough; j++ {
				if dp[j-cost] > -1<<30 {
					cand := dp[j-cost] + profit
					if cand > newDp[j] {
						newDp[j] = cand
					}
				}
			}
		}
		dp = newDp
	}

	// Now add the plain buns (without stuffing)
	// We can make any number of plain buns as long as dough allows
	// For each j (dough used by stuffed buns), we can use remaining dough (n - j) for plain buns
	// Number of plain buns = (n - j) / c0
	// Total money = dp[j] + ((n - j) / c0) * d0

	best := 0
	for j := 0; j <= maxDough; j++ {
