		stuffings[i].a, _ = fmt.Sscanf(parts[0], "%d")
		stuffings[i].b, _ = fmt.Sscanf(parts[1], "%d")
		stuffings[i].c, _ = fmt.Sscanf(parts[2], "%d")
		stuffings[i].d, _ = fmt.Sscanf(parts[3], "%d")
	}

	// dp[i][j] = max money using first i stuffings with j grams of dough used
	// We'll use 1D DP for dough
	// dp[j] = max money with j grams of dough used so far
	// Initialize with plain buns
	maxDough := n
	dp := make([]int, maxDough+1)
	for j := 0; j <= maxDough; j++ {
		if j%c0 == 0 {
			dp[j] = (j / c0) * d0
		} else {
			dp[j] = -1
		}
	}

	// For each stuffing type, update dp
	for i := 0; i < m; i++ {
		a, b, c, d := stuffings[i].a, stuffings[i].b, stuffings[i].c, stuffings[i].d
		maxBuns := a / b
		// newDp will be computed from dp
		newDp := make([]int, maxDough+1)
		copy(newDp, dp)
		for j := 0; j <= maxDough; j++ {
			if dp[j] < 0 {
				continue
			}
			// Try adding k buns of this stuffing
			for k := 1; k <= maxBuns; k++ {
				doughNeeded := k * c
				if j+doughNeeded > maxDough {
					break
				}
				val := dp[j] + k*d
				if val > newDp[j+doughNeeded] {
					newDp[j+doughNeeded] = val
				}
			}
		}
		copy(dp, newDp)
	}

	// Find max over all dough usage
	ans := 0
	for j := 0; j <= maxDough; j++ {
		if dp[j] > ans {
			ans = dp[j]
		}
	}
	fmt.Println(ans)
}
