		stuffings[i].b, _ = fmt.Sscanf(parts[1], "%d")
		stuffings[i].c, _ = fmt.Sscanf(parts[2], "%d")
		stuffings[i].d, _ = fmt.Sscanf(parts[3], "%d")
	}

	// dp[dough_used] = max money
	// We'll use a 2D DP: dp[i][dough] = max money after considering first i stuffings and using 'dough' grams
	// Actually, let's do iterative: for each stuffing type, update dp
