	"fmt"
	"os"
	"strings"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	line, _ := reader.ReadString('\n')
	fields := strings.Fields(line)
	n := parseInt(fields[0])
	m := parseInt(fields[1])
	c0 := parseInt(fields[2])
	d0 := parseInt(fields[3])

	type stuffing struct {
		a, b, c, d int
	}

	stuffings := make([]stuffing, m)
	for i := 0; i < m; i++ {
		line, _ = reader.ReadString('\n')
		fields = strings.Fields(line)
		stuffings[i] = stuffing{
			a: parseInt(fields[0]),
			b: parseInt(fields[1]),
			c: parseInt(fields[2]),
			d: parseInt(fields[3]),
		}
	}

	// dp[i][j] = max tugriks using first i stuffings and j grams of dough
	// i from 0 to m, j from 0 to n
	dp := make([][]int, m+1)
	for i := range dp {
		dp[i] = make([]int, n+1)
	}

	// Base case: no stuffings, only plain buns
	for j := 0; j <= n; j++ {
		dp[0][j] = (j / c0) * d0
	}

	for i := 1; i <= m; i++ {
		s := stuffings[i-1]
		maxBuns := s.a / s.b
		for j := 0; j <= n; j++ {
			best := dp[i-1][j]
			for k := 0; k <= maxBuns; k++ {
				doughUsed := k * s.c
				if doughUsed > j {
					break
				}
				val := dp[i-1][j-doughUsed] + k*s.d
				if val > best {
					best = val
				}
			}
			dp[i][j] = best
		}
	}

	fmt.Fprintf(writer, "%d\n", dp[m][n])
}

func parseInt(s string) int {
	var result int
	for _, c := range s {
		result = result*10 + int(c-'0')
	}
	return result
}
